#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>
#include <unistd.h>
#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <cstring>
#include <cmath>
#include <chrono>
#include <iostream>
#include "reference.h"

int main(int argc, char** argv)
{
  if (argc != 4)
  {
    printf("Usage: %s <input image> <output image> <iterations>\n", argv[0]) ;
    return -1 ;
  }

  unsigned short    input_image[Y_SIZE*X_SIZE] __attribute__((aligned(1024)));
  unsigned short    output_image[Y_SIZE*X_SIZE] __attribute__((aligned(1024)));
  unsigned short    output_image_ref[Y_SIZE*X_SIZE] __attribute__((aligned(1024)));

  // Read the bit map file into memory and allocate memory for the final image
  std::cout << "Reading input image...\n";

  // Load the input image
  const char *inputImageFilename = argv[1];
  FILE *input_file = fopen(inputImageFilename, "rb");
  if (!input_file)
  {
    printf("Error: Unable to open input image file %s!\n", inputImageFilename);
    return 1;
  }

  printf("\n");
  printf("   Reading RAW Image\n");
  size_t items_read = fread(input_image, sizeof(input_image), 1, input_file);
  printf("   Bytes read = %d\n\n", (int)(items_read * sizeof(input_image)));
  fclose(input_file);

  const int iterations = atoi(argv[3]);

  #pragma omp target data map(to: input_image[0:X_SIZE*Y_SIZE]) \
                          map(from:output_image[0:X_SIZE*Y_SIZE])
  {
    auto start = std::chrono::steady_clock::now();

    for (int i = 0; i < iterations; i++) {
      #pragma omp target teams distribute parallel for collapse(2) thread_limit(256)
      for (int y = 0; y < Y_SIZE; y++)
        for (int x = 0; x < X_SIZE; x++) {

          const float lx_rot   = 30.0f;
          const float ly_rot   = 0.0f; 
          const float lx_expan = 0.5f;
          const float ly_expan = 0.5f; 
          int   lx_move  = 0;
          int   ly_move  = 0;
          float affine[2][2];   // coefficients
          float i_affine[2][2];
          float beta[2];
          float i_beta[2];
          float det;
          float x_new, y_new;
          float x_frac, y_frac;
          float gray_new;
          int   m, n;
          unsigned short output_buffer;

          // forward affine transformation 
          affine[0][0] = lx_expan * cosf(lx_rot*PI/180.0f);
          affine[0][1] = ly_expan * sinf(ly_rot*PI/180.0f);
          affine[1][0] = lx_expan * sinf(lx_rot*PI/180.0f);
          affine[1][1] = ly_expan * cosf(ly_rot*PI/180.0f);
          beta[0]      = lx_move;
          beta[1]      = ly_move;

          // determination of inverse affine transformation
          det = (affine[0][0] * affine[1][1]) - (affine[0][1] * affine[1][0]);
          if (det == 0.0f)
          {
            i_affine[0][0] = 1.0f;
            i_affine[0][1] = 0.0f;
            i_affine[1][0] = 0.0f;
            i_affine[1][1] = 1.0f;
            i_beta[0]      = -beta[0];
            i_beta[1]      = -beta[1];
          } 
          else 
          {
            i_affine[0][0] =  affine[1][1]/det;
            i_affine[0][1] = -affine[0][1]/det;
            i_affine[1][0] = -affine[1][0]/det;
            i_affine[1][1] =  affine[0][0]/det;
            i_beta[0]      = -i_affine[0][0]*beta[0]-i_affine[0][1]*beta[1];
            i_beta[1]      = -i_affine[1][0]*beta[0]-i_affine[1][1]*beta[1];
          }

          // Output image generation by inverse affine transformation and bilinear transformation

          x_new  = i_beta[0] + i_affine[0][0]*(x-X_SIZE/2.0f) + i_affine[0][1]*(y-Y_SIZE/2.0f) + X_SIZE/2.0f;
          y_new  = i_beta[1] + i_affine[1][0]*(x-X_SIZE/2.0f) + i_affine[1][1]*(y-Y_SIZE/2.0f) + Y_SIZE/2.0f;

          m      = (int)floorf(x_new);
          n      = (int)floorf(y_new);

          x_frac = x_new - m;
          y_frac = y_new - n;

          if ((m >= 0) && (m + 1 < X_SIZE) && (n >= 0) && (n+1 < Y_SIZE))
          {
            gray_new = (1.0f - y_frac) * ((1.0f - x_frac) * (input_image[(n * X_SIZE) + m])  + 
                x_frac * (input_image[(n * X_SIZE) + m + 1])) + 
              y_frac  * ((1.0f - x_frac) * (input_image[((n + 1) * X_SIZE) + m]) + 
                  x_frac * (input_image[((n + 1) * X_SIZE) + m + 1]));

            output_buffer = (unsigned short)gray_new;
          } 
          else if (((m + 1 == X_SIZE) && (n >= 0) && (n < Y_SIZE)) || ((n + 1 == Y_SIZE) && (m >= 0) && (m < X_SIZE))) 
          {
            output_buffer = input_image[(n * X_SIZE) + m];
          } 
          else 
          {
            output_buffer = WHITE;
          }

          output_image[(y * X_SIZE)+x] = output_buffer;
        }
    }
    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    std::cout << "   Average kernel execution time " << (time * 1e-9f) / iterations << " (s)\n";
  }

  // verify
  affine_reference(input_image, output_image_ref);
  int max_error = 0;
  for (int y = 0; y < Y_SIZE; y++) {
    for (int x = 0; x < X_SIZE; x++) {
      max_error = std::max(max_error, std::abs(output_image[y*X_SIZE+x] - output_image_ref[y*X_SIZE+x]));
    }
  }
  printf("   Max output error is %d\n\n", max_error);

  printf("   Writing RAW Image\n");
  const char *outputImageFilename = argv[2];
  FILE *output_file = fopen(outputImageFilename, "wb");
  if (!output_file)
  {
    printf("Error: Unable to write  image file %s!\n", outputImageFilename);
    return 1;
  }
  size_t items_written = fwrite(output_image, sizeof(output_image), 1, output_file);
  printf("   Bytes written = %d\n\n", (int)(items_written * sizeof(output_image)));
  fclose(output_file);

  return 0 ;
}

/* This code is provided as supplementary material for the book
   chapter "Exploiting graphics processing units for computational
   biology and bioinformatics," by Payne, Sinnott-Armstrong, and
   Moore, to appear in "The Handbook of Research on Computational and
   Systems Biology: Interdisciplinary applications," by IGI Global.
 */

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <omp.h>
#include <sys/time.h>

#define INSTANCES 224   /* # of instances */
#define ATTRIBUTES 4096 /* # of attributes */
#define THREADS 128    /* # of threads per block */

struct char4 { char x; char y; char z; char w; };


/* CPU implementation */
void CPU(int * data, int * distance) {
  /* compare all pairs of instances, accessing the attributes in
     row-major order */
  #pragma omp parallel for collapse(2)
  for (int i = 0; i < INSTANCES; i++) {
    for (int j = 0; j < INSTANCES; j++) {
      for (int k = 0; k < ATTRIBUTES; k++) {
        distance[i + INSTANCES * j] += 
          (data[i * ATTRIBUTES + k] != data[j * ATTRIBUTES + k]);
      }
    }
  }
}

int main(int argc, char **argv) {

  if (argc != 2) {
    printf("Usage: %s <iterations>\n", argv[0]);
    return 1;
  }

  const int iterations = atoi(argv[1]);

  /* host data */
  int *data; 
  char *data_char;
  int *cpu_distance, *gpu_distance;

  /* used to time CPU and GPU implementations */
  double start_cpu, stop_cpu;
  double start_gpu, stop_gpu;
  double elapsedTime; 
  struct timeval tp;
  struct timezone tzp;
  /* verification result */ 
  int status;

  /* seed RNG */
  srand(2);

  /* allocate host memory */
  data = (int *)malloc(INSTANCES * ATTRIBUTES * sizeof(int));
  data_char = (char *)malloc(INSTANCES * ATTRIBUTES * sizeof(char));
  cpu_distance = (int *)malloc(INSTANCES * INSTANCES * sizeof(int));
  gpu_distance = (int *)malloc(INSTANCES * INSTANCES * sizeof(int));

  /* randomly initialize host data */
  #pragma omp parallel for collapse(2)
  for (int i = 0; i < ATTRIBUTES; i++) {
    for (int j = 0; j < INSTANCES; j++) {
      data[i + ATTRIBUTES * j] = data_char[i + ATTRIBUTES * j] = random() % 3;
    }
  }

  /* CPU */
  bzero(cpu_distance,INSTANCES*INSTANCES*sizeof(int));
  gettimeofday(&tp, &tzp);
  start_cpu = tp.tv_sec*1000000+tp.tv_usec;
  CPU(data, cpu_distance);
  gettimeofday(&tp, &tzp);
  stop_cpu = tp.tv_sec*1000000+tp.tv_usec;
  elapsedTime = stop_cpu - start_cpu;
  printf("CPU time: %f (us)\n",elapsedTime);

  #pragma omp target data map(to: data_char[0:INSTANCES * ATTRIBUTES]) \
                          map(alloc: gpu_distance[0:INSTANCES * INSTANCES ])
  {
    for (int n = 0; n < iterations; n++) {
      /* register-based kernel */
      bzero(gpu_distance,INSTANCES*INSTANCES*sizeof(int));
      #pragma omp target update to (gpu_distance[0:INSTANCES * INSTANCES])

      gettimeofday(&tp, &tzp);
      start_gpu = tp.tv_sec*1000000+tp.tv_usec;

      #pragma omp target teams num_teams(INSTANCES*INSTANCES) thread_limit(THREADS)
      {
        #pragma omp parallel
        {
          int idx = omp_get_thread_num();
          int gx = omp_get_team_num() % INSTANCES;
          int gy = omp_get_team_num() / INSTANCES;

          for(int i = 4*idx; i < ATTRIBUTES; i+=THREADS*4) {
            char4 j = *(char4 *)(data_char + i + ATTRIBUTES*gx);
            char4 k = *(char4 *)(data_char + i + ATTRIBUTES*gy);

            /* use a local variable (stored in register) to hold intermediate
               values. This reduces writes to global memory */
            char count = 0;

            if(j.x ^ k.x) 
              count++; 
            if(j.y ^ k.y)
              count++;
            if(j.z ^ k.z)
              count++;
            if(j.w ^ k.w)
              count++;

            /* atomic write to global memory */
            #pragma omp atomic update
            gpu_distance[ INSTANCES*gx + gy ] += count;
          }
        }
      }

      gettimeofday(&tp, &tzp);
      stop_gpu = tp.tv_sec*1000000+tp.tv_usec;
      elapsedTime += stop_gpu - start_gpu;
    }

    #pragma omp target update from (gpu_distance[0:INSTANCES * INSTANCES])

    printf("Average kernel execution time (w/o shared memory): %f (us)\n", elapsedTime / iterations);
    status = memcmp(cpu_distance, gpu_distance, INSTANCES * INSTANCES * sizeof(int));
    if (status != 0) printf("FAIL\n");
    else printf("PASS\n");

    elapsedTime = 0; 
    for (int n = 0; n < iterations; n++) {
      /* shared memory GPU kernel */
      bzero(gpu_distance,INSTANCES*INSTANCES*sizeof(int));
      #pragma omp target update to (gpu_distance[0:INSTANCES * INSTANCES])

      gettimeofday(&tp, &tzp);
      start_gpu = tp.tv_sec*1000000+tp.tv_usec;

      #pragma omp target teams num_teams(INSTANCES*INSTANCES) thread_limit(THREADS)
      {
        int dist[THREADS];
        #pragma omp parallel
        {
          int idx = omp_get_thread_num();
          int gx = omp_get_team_num() % INSTANCES;
          int gy = omp_get_team_num() / INSTANCES;

          dist[idx] = 0;
          #pragma omp barrier

          for(int i = 4*idx; i < ATTRIBUTES; i+=THREADS*4) {
            char4 j = *(char4 *)(data_char + i + ATTRIBUTES*gx);
            char4 k = *(char4 *)(data_char + i + ATTRIBUTES*gy);

            /* use a local variable (stored in register) to hold intermediate
               values. This reduces writes to global memory */
            char count = 0;

            if(j.x ^ k.x) 
              count++; 
            if(j.y ^ k.y)
              count++;
            if(j.z ^ k.z)
              count++;
            if(j.w ^ k.w)
              count++;

            dist[idx] += count;
          }

        /* Synchronize threads to make sure all have completed their updates
           of the shared array. Since the distances for each thread are read
           by thread 0 below, this must be ensured. Above, it was not
           necessary because each thread was accessing its own memory
        */
          #pragma omp barrier

          /* Perform balanced tree reduction across the shared memory */
          for (int stride = THREADS/2; stride > 0; stride /= 2) {
            if (idx < stride) {
              dist[idx] += dist[idx + stride];
            }
            #pragma omp barrier
          }

            /* Thread 0 will then write the output to global memory. Note that
               this does not need to be performed atomically, because only one
               thread per block is writing to global memory, and each block
               corresponds to a unique memory address. 
            */
          if(idx == 0) {
            gpu_distance[INSTANCES*gy + gx] = dist[0];
          }
        }
      }

      gettimeofday(&tp, &tzp);
      stop_gpu = tp.tv_sec*1000000+tp.tv_usec;
      elapsedTime += stop_gpu - start_gpu;
    }

    #pragma omp target update from (gpu_distance[0:INSTANCES * INSTANCES])

    printf("Average kernel execution time (w/ shared memory): %f (us)\n", elapsedTime / iterations);
    status = memcmp(cpu_distance, gpu_distance, INSTANCES * INSTANCES * sizeof(int));
    if (status != 0) printf("FAIL\n");
    else printf("PASS\n");
  }

  free(cpu_distance);
  free(gpu_distance);
  free(data_char);
  free(data);
  return status;
}

#include <stdlib.h>
#include <stdio.h>
#include <math.h>
#include <chrono>
#include <omp.h>

#include "reference.h"

int main(int argc, char* argv[]) {
  if (argc != 5) {
    printf("./%s <image dimension> <threshold> <max box size> <iterations>\n", argv[0]);
    exit(1);
  }

  // only a square image is supported
  const int Lx = atoi(argv[1]);
  const int Ly = Lx;
  const int size = Lx * Ly;

  const int Threshold = atoi(argv[2]);
  const int MaxRad = atoi(argv[3]);
  const int repeat = atoi(argv[4]);

  const size_t size_bytes = size * sizeof(float);
  const size_t box_bytes = size * sizeof(int);

  // input image
  float *img = (float*) malloc (size_bytes);

  // host and device results
  float *norm = (float*) malloc (size_bytes);
  float *h_norm = (float*) malloc (size_bytes);

  int *box = (int*) malloc (box_bytes);
  int *h_box = (int*) malloc (box_bytes);

  float *out = (float*) malloc (size_bytes);
  float *h_out = (float*) malloc (size_bytes);

  srand(123);
  for (int i = 0; i < size; i++) {
    img[i] = rand() % 256;
    norm[i] = box[i] = out[i] = 0;
  }

  double time = 0;

  #pragma omp target data map(alloc: img[0:size], norm[0:size], box[0:size]) \
                          map(to: out[0:size]) 
  {
    for (int i = 0; i < repeat; i++) {
      // restore input image
      #pragma omp target update to(img[0:size])
      // reset norm
      #pragma omp target update to(norm[0:size])

      auto start = std::chrono::steady_clock::now();

      // launch three kernels
      #pragma omp target teams distribute parallel for collapse(2) thread_limit(256)
      for (int x = 0; x < Lx; x++) {
        for (int y = 0; y < Ly; y++) {
          float sum = 0.f;
          int s = 1;
          int q = 1;
          int ksum = 0;

          while (sum < Threshold && q < MaxRad) {
            s = q;
            sum = 0.f;
            ksum = 0;

            for (int i = -s; i < s+1; i++)
              for (int j = -s; j < s+1; j++)
                if (x-s >=0 && x+s < Lx && y-s >=0 && y+s < Ly) {
                  sum += img[(x+i)*Ly+y+j];
                  ksum++;
                }
            q++;
          }

          box[x*Ly+y] = s;  // save the box size

          for (int i = -s; i < s+1; i++)
            for (int j = -s; j < s+1; j++)
              if (x-s >=0 && x+s < Lx && y-s >=0 && y+s < Ly)
                if (ksum != 0) {
                  #pragma omp atomic update
                  norm[(x+i)*Ly+y+j] += 1.f / (float)ksum;
                }
        }
      }

      // normalize the image
      #pragma omp target teams distribute parallel for collapse(2) thread_limit(256)
      for (int x = 0; x < Lx; x++)
        for (int y = 0; y < Ly; y++) 
          if (norm[x*Ly+y] != 0) img[x*Ly+y] /= norm[x*Ly+y];

      // output file
      #pragma omp target teams distribute parallel for collapse(2) thread_limit(256)
      for (int x = 0; x < Lx; x++) {
        for (int y = 0; y < Ly; y++) {
          int s = box[x*Ly+y];
          float sum = 0.f;
          int ksum = 0;

          // resmooth with normalized image
          for (int i = -s; i < s+1; i++)
            for (int j = -s; j < s+1; j++) {
              if (x-s >=0 && x+s < Lx && y-s >=0 && y+s < Ly) {
                sum += img[(x+i)*Ly+y+j];
                ksum++;
              }
            }
          if (ksum != 0) out[x*Ly+y] = sum / (float)ksum;
        }
      }
      auto end = std::chrono::steady_clock::now();
      time += std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    }

    printf("Average filtering time %lf (s)\n", (time * 1e-9) / repeat);

    #pragma omp target update from(out[0:size])
    #pragma omp target update from(box[0:size])
    #pragma omp target update from(norm[0:size])
  }

  // verify
  reference (Lx, Ly, Threshold, MaxRad, img, h_box, h_norm, h_out);
  verify(size, MaxRad, norm, h_norm, out, h_out, box, h_box);

  free(img);
  free(norm);
  free(h_norm);
  free(box);
  free(h_box);
  free(out);
  free(h_out);
  return 0;
}

