#pragma omp declare target
INLINE
uchar* image_pixel_at_(uchar *im_p, const uint im_rows, const uint im_cols, const uint image_pitch_p, 
                       const uint r, const uint c, const uint sizeof_pixel) {
  assert_val(r >= 0 && r < im_rows, r);
