#pragma omp declare target
inline void clip_plus( const bool &clip, const int &n, int &plus ) {
  if ( plus >= n ) plus = clip ? n - 1 : plus - n;
}
#pragma omp end declare target

#pragma omp declare target
inline void clip_minus( const bool &clip, const int &n, int &minus ) {
  if ( minus < 0 ) minus = clip ? 0 : minus + n;
}
#pragma omp end declare target

template <typename T>
long test_1D (const int length, const int order, const bool clip,
              const int repeat, const char* type) 
{
  T* inp = (T*) malloc (sizeof(T)*length);
  for (int i = 0; i < length; i++)
    inp[i] = rand() % length;

  bool* cpu_r = (bool*) malloc (sizeof(bool)*length);
  bool* gpu_r = (bool*) malloc (sizeof(bool)*length);

  long time;
  #pragma omp target data map(to: inp[0:length]) map(from: gpu_r[0:length])
  {
    auto start = std::chrono::steady_clock::now();

    for (int n = 0; n < repeat; n++) {
      #pragma omp target teams distribute parallel for thread_limit(256)
      for (int tid = 0; tid < length; tid++) {
        const T data = inp[tid];
        bool    temp = true;

        for ( int o = 1; o <= order; o++ ) {
          int plus = tid + o;
          int minus = tid - o;

          clip_plus( clip, length, plus );
          clip_minus( clip, length, minus );

          temp &= data > inp[plus];
          temp &= data >= inp[minus];
        }
        gpu_r[tid] = temp;
      }
    }

    auto end = std::chrono::steady_clock::now();
    time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average 1D kernel (type = %s, order = %d, clip = %d) execution time %f (s)\n", 
           type, order, clip, (time * 1e-9f) / repeat);
  }

  cpu_relextrema_1D<T>(length, order, clip, inp, cpu_r);

  int error = 0;
  for (int i = 0; i < length; i++)
    if (cpu_r[i] != gpu_r[i]) {
      error = 1; 
      break;
    }

  free(inp);
  free(cpu_r);
  free(gpu_r);
  if (error) printf("1D test: FAILED\n");
  return time;
}

// length_x is the number of columns
// length_y is the number of rows
template <typename T>
long test_2D (const int length_x, const int length_y, const int order,
              const bool clip, const int axis, const int repeat, const char* type) 
{
  const int length = length_x * length_y;
  T* inp = (T*) malloc (sizeof(T)*length);
  for (int i = 0; i < length; i++)
    inp[i] = rand() % length;

  bool* cpu_r = (bool*) malloc (sizeof(bool)*length);
  bool* gpu_r = (bool*) malloc (sizeof(bool)*length);

  long time = 0;
  #pragma omp target data map(to: inp[0:length]) map(from: gpu_r[0:length])
  {
    auto start = std::chrono::steady_clock::now();

    for (int n = 0; n < repeat; n++)  {
      #pragma omp target teams distribute parallel for collapse(2) thread_limit(256)
      for (int tx = 0; tx < length_y; tx++)
        for (int ty = 0; ty < length_x; ty++) {
          int tid = tx * length_x + ty ;
          const T data = inp[tid] ;
          bool    temp = true ;

          for ( int o = 1; o <= order; o++ ) {
            int plus;
            int minus;
            if ( axis == 0 ) {
              plus  = tx + o;
              minus = tx - o;

              clip_plus( clip, length_y, plus );
              clip_minus( clip, length_y, minus );

              plus  = plus * length_x + ty;
              minus = minus * length_x + ty;
            } else {
              plus  = ty + o;
              minus = ty - o;

              clip_plus( clip, length_x, plus );
              clip_minus( clip, length_x, minus );

              plus  = tx * length_x + plus;
              minus = tx * length_x + minus;
            }
            temp &= data > inp[plus] ;
            temp &= data >= inp[minus] ;
          }
          gpu_r[tid] = temp;
        }
    }

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average 2D kernel (type = %s, order = %d, clip = %d, axis = %d) execution time %f (s)\n", 
           type, order, clip, axis, (time * 1e-9f) / repeat);
  }

  cpu_relextrema_2D(length_x, length_y, order, clip, axis, inp, cpu_r);

  int error = 0;
  for (int i = 0; i < length; i++)
    if (cpu_r[i] != gpu_r[i]) {
      error = 1; 
      break;
    }

  free(inp);
  free(cpu_r);
  free(gpu_r);
  if (error) printf("2D test: FAILED\n");
  return time;
}

int main(int argc, char* argv[]) {
  if (argc != 2) {
    printf("Usage ./%s <repeat>\n", argv[0]);
    return 1;
  }
  const int repeat = atoi(argv[1]);

  long time = 0;
  for (int order = 1; order <= 128; order = order * 2) {
    time += test_1D<   int>(1000000, order, true, repeat, "int");
    time += test_1D<  long>(1000000, order, true, repeat, "long");
    time += test_1D< float>(1000000, order, true, repeat, "float");
    time += test_1D<double>(1000000, order, true, repeat, "double");
  }

  for (int order = 1; order <= 128; order = order * 2) {
    time += test_2D<   int>(1000, 1000, order, true, 1, repeat, "int");
    time += test_2D<  long>(1000, 1000, order, true, 1, repeat, "long");
    time += test_2D< float>(1000, 1000, order, true, 1, repeat, "float");
    time += test_2D<double>(1000, 1000, order, true, 1, repeat, "double");
  }

  for (int order = 1; order <= 128; order = order * 2) {
    time += test_2D<   int>(1000, 1000, order, true, 0, repeat, "int");
    time += test_2D<  long>(1000, 1000, order, true, 0, repeat, "long");
    time += test_2D< float>(1000, 1000, order, true, 0, repeat, "float");
    time += test_2D<double>(1000, 1000, order, true, 0, repeat, "double");
  }

  printf("\n-----------------------------------------------\n");
  printf("Total kernel execution time: %lf (s)", time * 1e-9);
  printf("\n-----------------------------------------------\n");

  return 0;
}

#include <cstdio>
#include <cstdlib>
#include <cstring>
#include <vector>
#include <chrono>
#include <omp.h>
#include "reference.h"

void ga(const char *__restrict target,
        const char *__restrict query,
              char *__restrict batch_result,
              uint32_t length,
              int query_sequence_length,
              int coarse_match_length,
              int coarse_match_threshold,
              int current_position)
{
  #pragma omp target teams distribute parallel for thread_limit(256)
  for (uint tid = 0; tid < length; tid++) { 
    bool match = false;
    int max_length = query_sequence_length - coarse_match_length;

    for (int i = 0; i <= max_length; i++) {
      int distance = 0;
      for (int j = 0; j < coarse_match_length; j++) {
        if (target[current_position + tid + j] != query[i + j]) {
          distance++;
        }
      }

      if (distance < coarse_match_threshold) {
        match = true;
        break;
      }
    }
    if (match) {
      batch_result[tid] = 1;
    }
  }
}

int main(int argc, char* argv[]) 
{
  if (argc != 5) {
    printf("Usage: %s <target sequence length> <query sequence length> "
           "<coarse match length> <coarse match threshold>\n", argv[0]);
    return 1;
  }

  const int kBatchSize = 1024;
  char seq[] = {'A', 'C', 'T', 'G'};
  const int tseq_size = atoi(argv[1]);
  const int qseq_size = atoi(argv[2]);
  const int coarse_match_length = atoi(argv[3]);
  const int coarse_match_threshold = atoi(argv[4]);

  std::vector<char> target_sequence(tseq_size);
  std::vector<char> query_sequence(qseq_size);

  srand(123);
  for (int i = 0; i < tseq_size; i++) target_sequence[i] = seq[rand()%4];
  for (int i = 0; i < qseq_size; i++) query_sequence[i] = seq[rand()%4];

  char *d_target = target_sequence.data(); 
  char *d_query = query_sequence.data();

  uint32_t max_searchable_length = tseq_size - coarse_match_length;
  uint32_t current_position = 0;

  // host and device results
  char d_batch_result[kBatchSize];
  char batch_result_ref[kBatchSize];

  float total_time = 0.f;

  int error = 0;

  #pragma omp target data map (to: d_target[0:tseq_size], \
                                   d_query[0:qseq_size]) \
                          map (alloc: d_batch_result[0:kBatchSize])
  {
    while (current_position < max_searchable_length) {
      #pragma omp target teams distribute parallel for thread_limit(256)
      for (int i = 0; i < kBatchSize; i++)
        d_batch_result[i] = 0;

      memset(batch_result_ref, 0, kBatchSize);

      uint32_t end_position = current_position + kBatchSize;
      if (end_position >= max_searchable_length) {
        end_position = max_searchable_length;
      }
      uint32_t length = end_position - current_position;

      auto start = std::chrono::steady_clock::now();

      ga( d_target, d_query, d_batch_result, length, qseq_size,
          coarse_match_length, coarse_match_threshold, current_position);

      auto end = std::chrono::steady_clock::now();
      auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
      total_time += time;

      reference(target_sequence.data(), query_sequence.data(), batch_result_ref, length, qseq_size,
                coarse_match_length, coarse_match_threshold, current_position);

      #pragma omp target update from (d_batch_result[0:kBatchSize])
      error = memcmp(batch_result_ref, d_batch_result, kBatchSize * sizeof(char));
      if (error) break;

      current_position = end_position;
    }
  }
  printf("Total kernel execution time %f (s)\n", total_time * 1e-9f);
  printf("%s\n", error ? "FAIL" : "PASS");
  return 0;
}

#include <math.h>
#include <sys/time.h>
#include "gaussianElim.h"

#define BLOCK_SIZE_0 256

long long get_time() {
  struct timeval tv;
  gettimeofday(&tv, NULL);
  return (tv.tv_sec * 1000000) +tv.tv_usec;
}

// create both matrix and right hand side, Ke Wang 2013/08/12 11:51:06
void init_matrix(float *m, int size){
  int i,j;
  float lamda = -0.01;
  float coe[2*size-1];
  float coe_i =0.0;

  for (i=0; i < size; i++)
  {
    coe_i = 10*exp(lamda*i); 
    j=size-1+i;     
    coe[j]=coe_i;
    j=size-1-i;     
    coe[j]=coe_i;
  }

  for (i=0; i < size; i++) {
    for (j=0; j < size; j++) {
      m[i*size+j]=coe[size-1-i+j];
    }
  }
}

// reference implementation for verification
void gaussian_reference(float *a, float *b, float *m, float* finalVec, int size) {
  for (int t=0; t<(size-1); t++) {
    for (int i = 0; i < size-1-t; i++) {
      m[size * (i + t + 1)+t] = 
        a[size * (i + t + 1) + t] / a[size * t + t];
    }
    for (int x = 0; x < size-1-t; x++) {
      for (int y = 0; y < size-t; y++) {
        a[size * (x + t + 1)+y+t] -= 
          m[size * (x + t + 1) + t] * a[size * t + y + t];
        if (y == 0)
          b[x+1+t] -= m[size*(x+1+t)+(y+t)] * b[t];
      }
    }
  }

  BackSub(a,b,finalVec,size);
}

int main(int argc, char *argv[]) {

  float *a=NULL, *b=NULL, *finalVec=NULL;
  float *m=NULL;
  int size = -1;

  FILE *fp;

  // args
  char filename[200];
  int quiet=0,timing=0;

  // parse command line
  if (parseCommandline(argc, argv, filename, &quiet, &timing, &size)) {
    printUsage();
    return 0;
  }

  if(size < 1)
  {
    fp = fopen(filename, "r");
    fscanf(fp, "%d", &size);

    a = (float *) malloc(size * size * sizeof(float));
    InitMat(fp,size, a, size, size);

    b = (float *) malloc(size * sizeof(float));
    InitAry(fp, b, size);

    fclose(fp);
  }
  else
  {
    a = (float *) malloc(size * size * sizeof(float));
    init_matrix(a, size);

    b = (float *) malloc(size * sizeof(float));
    for (int i =0; i< size; i++)
      b[i]=1.0;
  }

  if (!quiet) {    
    printf("The input matrix a is:\n");
    PrintMat(a, size, size, size);

    printf("The input array b is:\n");
    PrintAry(b, size);
  }

  // create the solution matrix
  m = (float *) malloc(size * size * sizeof(float));
  InitPerRun(size,m);

  // create a new vector to hold the final answer
  finalVec = (float *) malloc(size * sizeof(float));

  // verification
  float* a_host = (float *) malloc(size * size * sizeof(float));
  memcpy(a_host, a, size * size * sizeof(float));
  float* b_host = (float *) malloc(size * sizeof(float));
  memcpy(b_host, b, size*sizeof(float));
  float* m_host = (float *) malloc(size * size * sizeof(float));
  memcpy(m_host, m, size*size*sizeof(float));
  float* finalVec_host = (float *) malloc(size * sizeof(float));

  // Compute the reference on a host
  gaussian_reference(a_host, b_host, m_host, finalVec_host, size);

  // Compute the forward phase on a device
  long long offload_start = get_time();
  ForwardSub(a,b,m,size,timing);
  long long offload_end = get_time();

  if (timing) {
    printf("Device offloading time %lld (us)\n\n",offload_end - offload_start);
  }

  //end timing

  // Compute the backward phase on a host
  BackSub(a,b,finalVec,size);

  if (!quiet) {
    printf("The result of array a is after forwardsub: \n");
    PrintMat(a, size, size, size);
    printf("The result of array b is after forwardsub: \n");
    PrintAry(b, size);
    printf("The result of matrix m is after forwardsub: \n");
    PrintMat(m, size, size, size);
    printf("The solution is: \n");
    PrintAry(finalVec,size);
  }

  // verification
  printf("Checking the results..\n");
  bool ok = true;
  for (int i = 0; i < size; i++) {
    if (fabsf(finalVec[i] - finalVec_host[i]) > 1e-3) {
      ok = false; 
      printf("Result mismatch at index %d: %f(device)  %f(host)\n", 
          i, finalVec[i], finalVec_host[i]);
    }
  }
  printf("%s\n", ok ? "PASS" : "FAIL");

  free(m);
  free(a);
  free(b);
  free(finalVec);

  // verification
  free(a_host);
  free(m_host);
  free(b_host);
  free(finalVec_host);
  return 0;
}

/*------------------------------------------------------
 ** ForwardSub() -- Forward substitution of Gaussian
 ** elimination.
 **------------------------------------------------------
 */
void ForwardSub(float *a, float *b, float *m, int size, int timing) {
#pragma omp target data map(tofrom: a[0:size*size], b[0:size], m[0:size*size])
  {
    auto start = get_time();

    for (int t=0; t<(size-1); t++) {

      #pragma omp target teams distribute parallel for thread_limit(BLOCK_SIZE_0)
      for (int i = 0; i < size - 1 - t; i++) {
        m[size * (i + t + 1)+t] = 
          a[size * (i + t + 1) + t] / a[size * t + t];
      }

      #pragma omp target teams distribute parallel for collapse(2) thread_limit(BLOCK_SIZE_0)
      for (int x = 0; x < size - 1 - t; x++) {
        for (int y = 0; y < size - t; y++) {
          a[size*(x+1+t)+(y+t)] -= m[size*(x+1+t)+t] * a[size*t+(y+t)];

          if(y == 0){
            b[x+1+t] -= m[size*(x+1+t)+(y+t)] * b[t];
          }
        }
      }
    } // for (t=0; t<(size-1); t++) 

    auto end = get_time();
    if (timing)
      printf("Total kernel execution time %lld (us)\n", (end - start));
  }
}

// Ke Wang add a function to generate input internally
int parseCommandline(int argc, char *argv[], char* filename,
    int *q, int *t, int *size){
  int i;
  if (argc < 2) return 1; // error
  // strncpy(filename,argv[1],100);
  char flag;

  for(i=1;i<argc;i++) {
    if (argv[i][0]=='-') {// flag
      flag = argv[i][1];
      switch (flag) {
        case 's': // matrix size
          i++;
          *size = atoi(argv[i]);
          printf("Create a square matrix (%d x %d) internally\n", *size, *size);
          break;
        case 'f': // file name
          i++;
          strncpy(filename,argv[i],100);
          printf("Read file from %s \n", filename);
          break;
        case 'h': // help
          return 1; 
        case 'q': // quiet
          *q = 1;
          break;
        case 't': // timing
          *t = 1;
          break;
      }
    }
  }
  return 0;
}

