///////////////////////////////////////////////////////////////////////////////

/*
   import cupy as cp
   import matplotlib.pyplot as plt
   First define some input parameters for the signal:
   A = 2.
   w = 1.
   phi = 0.5 * cp.pi
   nin = 10000
   nout = 1000000
   r = cp.random.rand(nin)
   x = cp.linspace(0.01, 10*cp.pi, nin)
   Plot a sine wave for the selected times:
   y = A * cp.sin(w*x+phi)
   Define the array of frequencies for which to compute the periodogram:
   f = cp.linspace(0.01, 10, nout)
   Calculate Lomb-Scargle periodogram:
   pgram = cusignal.lombscargle(x, y, f, normalize=True)
   */

#include <math.h>
#include <stdlib.h>
#include <stdio.h>
#include <chrono>

void lombscargle_cpu( const int x_shape,
    const int freqs_shape,
    const float *__restrict x,
    const float *__restrict y,
    const float *__restrict freqs,
    float *__restrict pgram,
    const float y_dot )
{
  for ( int tid = 0; tid < freqs_shape; tid ++ ) {

    float freq = freqs[tid] ;
    float xc = 0;
    float xs = 0;
    float cc = 0;
    float ss = 0;
    float cs = 0;
    float c;
    float s; 

    for ( int j = 0; j < x_shape; j++ ) {
      sincosf( freq * x[j], &s, &c );
      xc += y[j] * c;
      xs += y[j] * s;
      cc += c * c;
      ss += s * s;
      cs += c * s;
    }

    float c_tau;
    float s_tau;
    float tau = atan2f( 2.0f * cs, cc - ss ) / ( 2.0f * freq ) ;
    sincosf( freq * tau, &s_tau, &c_tau );
    float c_tau2 = c_tau * c_tau ;
    float s_tau2 = s_tau * s_tau ;
    float cs_tau = 2.0f * c_tau * s_tau ;

    pgram[tid] = ( 0.5f * ( ( ( c_tau * xc + s_tau * xs ) * ( c_tau * xc + s_tau * xs ) /
            ( c_tau2 * cc + cs_tau * cs + s_tau2 * ss ) ) +
          ( ( c_tau * xs - s_tau * xc ) * ( c_tau * xs - s_tau * xc ) /
            ( c_tau2 * ss - cs_tau * cs + s_tau2 * cc ) ) ) ) * y_dot;
  }
}

int main(int argc, char* argv[]) {
  if (argc != 2) {
    printf("Usage: %s <repeat>\n", argv[0]);
    return 1;
  }
  const int repeat = atoi(argv[1]);

  const int x_shape = 1000;
  const int freqs_shape = 100000;
  const float A = 2.f;
  const float w = 1.0f;
  const float phi = 1.57f; 

  float* x = (float*) malloc (sizeof(float)*x_shape); 
  float* y = (float*) malloc (sizeof(float)*x_shape); 
  float* f = (float*) malloc (sizeof(float)*freqs_shape); 
  float* p  = (float*) malloc (sizeof(float)*freqs_shape); 
  float* p2 = (float*) malloc (sizeof(float)*freqs_shape); 

  for (int i = 0; i < x_shape; i++)
    x[i] = 0.01f + i*(31.4f - 0.01f)/x_shape;

  for (int i = 0; i < x_shape; i++)
    y[i] = A * sinf(w*x[i]+phi);

  for (int i = 0; i < freqs_shape; i++)
    f[i] = 0.01f + i*(10.f-0.01f)/freqs_shape;

  const float y_dot = 2.0f/1.5f;

  #pragma omp target data map(to: x[0:x_shape], y[0:x_shape], f[0:freqs_shape]) \
                          map(from: p[0:freqs_shape])
  {
    auto start = std::chrono::steady_clock::now();

    for (int n = 0; n < repeat; n++) {
      #pragma omp target teams distribute parallel for thread_limit(256)
      for ( int tid = 0; tid < freqs_shape; tid++) {

        float freq = f[tid] ;

        float xc = 0;
        float xs = 0;
        float cc = 0;
        float ss = 0;
        float cs = 0;
        float c;
        float s; 

        for ( int j = 0; j < x_shape; j++ ) {
          sincosf( freq * x[j], &s, &c );
          xc += y[j] * c;
          xs += y[j] * s;
          cc += c * c;
          ss += s * s;
          cs += c * s;
        }

        float c_tau;
        float s_tau;
        float tau = atan2f( 2.0f * cs, cc - ss ) / ( 2.0f * freq ) ;
        sincosf( freq * tau, &s_tau, &c_tau );
        float c_tau2 = c_tau * c_tau ;
        float s_tau2 = s_tau * s_tau ;
        float cs_tau = 2.0f * c_tau * s_tau ;

        p[tid] = ( 0.5f * ( ( ( c_tau * xc + s_tau * xs ) * ( c_tau * xc + s_tau * xs ) /
                ( c_tau2 * cc + cs_tau * cs + s_tau2 * ss ) ) +
              ( ( c_tau * xs - s_tau * xc ) * ( c_tau * xs - s_tau * xc ) /
                ( c_tau2 * ss - cs_tau * cs + s_tau2 * cc ) ) ) ) * y_dot;
      }
    }

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time %f (us)\n", (time * 1e-3) / repeat);
  }

  // verification
  lombscargle_cpu(x_shape, freqs_shape, x, y, f, p2, y_dot);

  bool error = false;
  for (int i = 0; i < freqs_shape; i++) {
    if (fabsf(p[i]-p2[i]) > 1e-1f) {
      printf("%.3f %.3f\n", p[i], p2[i]);
      error = true;
      break;
    }
  }

  printf("%s\n", error ? "FAIL" : "PASS");

  free(x);
  free(y);
  free(f);
  free(p);
  free(p2);
  return 0;
}

#include <stdio.h>
#include <unistd.h>
#include <getopt.h>
#include <stdlib.h>
#include <assert.h>
#include <sys/time.h>
#include <string.h>
#include <chrono>
#include <omp.h>
#include "common.h"

#define BLOCK_SIZE 16

double gettime() {
  struct timeval t;
  gettimeofday(&t,NULL);
  return t.tv_sec+t.tv_usec*1e-6;
}

static int do_verify = 0;

static struct option long_options[] = {
  /* name, has_arg, flag, val */
  {"input", 1, NULL, 'i'},
  {"size", 1, NULL, 's'},
  {"verify", 0, NULL, 'v'},
  {0,0,0,0}
};

int main ( int argc, char *argv[] )
{
  int matrix_dim = 32; /* default matrix_dim */
  int opt, option_index=0;
  func_ret_t ret;
  const char *input_file = NULL;
  float *m, *mm;
  stopwatch sw;

  while ((opt = getopt_long(argc, argv, "::vs:i:", 
          long_options, &option_index)) != -1 ) {
    switch(opt){
      case 'i':
        input_file = optarg;
        break;
      case 'v':
        do_verify = 1;
        break;
      case 's':
        matrix_dim = atoi(optarg);
        if (matrix_dim <= 0) {
          printf("Matrix dimension must be positive!\n");
          exit(EXIT_FAILURE);
        }
        if (matrix_dim % 16 != 0) {
          printf("Matrix dimension of %d not supported by the benchmark\n", matrix_dim);
          exit(EXIT_FAILURE);
        }
        printf("Generate input matrix internally, size =%d\n", matrix_dim);
        break;
      case '?':
        fprintf(stderr, "invalid option\n");
        break;
      case ':':
        fprintf(stderr, "missing argument\n");
        break;
      default:
        fprintf(stderr, "Usage: %s [-v] [-s matrix_size|-i input_file]\n",
            argv[0]);
        exit(EXIT_FAILURE);
    }
  }

  if ( (optind < argc) || (optind == 1)) {
    fprintf(stderr, "Usage: %s [-v] [-s matrix_size|-i input_file]\n", argv[0]);
    exit(EXIT_FAILURE);
  }  

  if (input_file) {
    printf("Reading matrix from file %s\n", input_file);
    ret = create_matrix_from_file(&m, input_file, &matrix_dim);
    if (ret != RET_SUCCESS) {
      m = NULL;
      fprintf(stderr, "error create matrix from file %s\n", input_file);
      exit(EXIT_FAILURE);
    }
  } 

  else if (matrix_dim) {
    printf("Creating matrix internally size=%d\n", matrix_dim);
    ret = create_matrix(&m, matrix_dim);
    if (ret != RET_SUCCESS) {
      m = NULL;
      fprintf(stderr, "error create matrix internally size=%d\n", matrix_dim);
      exit(EXIT_FAILURE);
    }
  }
  else {
    printf("No input file specified!\n");
    exit(EXIT_FAILURE);
  }

  if (do_verify){
    printf("Before LUD\n");
    // print_matrix(m, matrix_dim);
    matrix_duplicate(m, &mm, matrix_dim);
  }

  printf("WG size of kernel = %d X %d\n", BLOCK_SIZE, BLOCK_SIZE);

  /* beginning of timing point */
  stopwatch_start(&sw);

  #pragma omp target data map(tofrom: m[0:(size_t)matrix_dim*matrix_dim])
  {
  int offset;
  int i=0;

  auto start = std::chrono::steady_clock::now();

  for (i=0; i < matrix_dim-BLOCK_SIZE; i += BLOCK_SIZE) {
    offset = i;  // add the offset 
    #pragma omp target teams num_teams(1) thread_limit(BLOCK_SIZE)
    {
      float shadow[BLOCK_SIZE * BLOCK_SIZE];
      #pragma omp parallel
      {
        int i,j;
        int tx = omp_get_thread_num() ;

        size_t array_offset = offset*(size_t)matrix_dim+offset;
        for(i=0; i < BLOCK_SIZE; i++){
          shadow[i * BLOCK_SIZE + tx]=m[array_offset + tx];
          array_offset += matrix_dim;
        }

        #pragma omp barrier

        for(i=0; i < BLOCK_SIZE-1; i++) {

          if (tx>i){
            for(j=0; j < i; j++)
              shadow[tx * BLOCK_SIZE + i] -= shadow[tx * BLOCK_SIZE + j] * shadow[j * BLOCK_SIZE + i];
          shadow[tx * BLOCK_SIZE + i] /= shadow[i * BLOCK_SIZE + i];
          }

          #pragma omp barrier
          if (tx>i){

            for(j=0; j < i+1; j++)
              shadow[(i+1) * BLOCK_SIZE + tx] -= shadow[(i+1) * BLOCK_SIZE + j]*shadow[j * BLOCK_SIZE + tx];
          }

          #pragma omp barrier
        }

        array_offset = (offset+1)*(size_t)matrix_dim+offset;
        for(i=1; i < BLOCK_SIZE; i++){
          m[array_offset+tx]=shadow[i * BLOCK_SIZE + tx];
          array_offset += matrix_dim;
        }
      }
    }

    #pragma omp target teams num_teams((matrix_dim-i)/BLOCK_SIZE-1) thread_limit(2*BLOCK_SIZE)
    {
      float dia[BLOCK_SIZE * BLOCK_SIZE];
      float peri_row[BLOCK_SIZE * BLOCK_SIZE];
      float peri_col[BLOCK_SIZE * BLOCK_SIZE];
      #pragma omp parallel
      {
         size_t array_offset;
         int i,j;
         int idx;

         int  bx = omp_get_team_num();  
         int  tx = omp_get_thread_num();

         if (tx < BLOCK_SIZE) {
           idx = tx;
           array_offset = offset*(size_t)matrix_dim+offset;
           for (i=0; i < BLOCK_SIZE/2; i++){
           dia[i * BLOCK_SIZE + idx]=m[array_offset+idx];
           array_offset += matrix_dim;
           }

         array_offset = offset*(size_t)matrix_dim+offset;
         for (i=0; i < BLOCK_SIZE; i++) {
           peri_row[i * BLOCK_SIZE+ idx]=m[array_offset+(bx+1)*BLOCK_SIZE+idx];
           array_offset += matrix_dim;
         }

         } else {
         idx = tx-BLOCK_SIZE;

         array_offset = (offset+BLOCK_SIZE/2)*(size_t)matrix_dim+offset;
         for (i=BLOCK_SIZE/2; i < BLOCK_SIZE; i++){
           dia[i * BLOCK_SIZE + idx]=m[array_offset+idx];
           array_offset += matrix_dim;
         }

         array_offset = (offset+(bx+1)*BLOCK_SIZE)*(size_t)matrix_dim+offset;
         for (i=0; i < BLOCK_SIZE; i++) {
           peri_col[i * BLOCK_SIZE + idx] = m[array_offset+idx];
           array_offset += matrix_dim;
         }
       }
       #pragma omp barrier

       if (tx < BLOCK_SIZE) { //peri-row
         idx=tx;
         for(i=1; i < BLOCK_SIZE; i++){
           for (j=0; j < i; j++)
             peri_row[i * BLOCK_SIZE + idx]-=dia[i * BLOCK_SIZE+ j]*peri_row[j * BLOCK_SIZE + idx];
         }
       } else { //peri-col
         idx=tx - BLOCK_SIZE;
         for(i=0; i < BLOCK_SIZE; i++){
           for(j=0; j < i; j++)
             peri_col[idx * BLOCK_SIZE + i]-=peri_col[idx * BLOCK_SIZE+ j]*dia[j * BLOCK_SIZE + i];
            peri_col[idx * BLOCK_SIZE + i] /= dia[i * BLOCK_SIZE+ i];
         }
       }

       #pragma omp barrier
       if (tx < BLOCK_SIZE) { //peri-row
         idx=tx;
         array_offset = (offset+1)*(size_t)matrix_dim+offset;
         for(i=1; i < BLOCK_SIZE; i++){
           m[array_offset+(bx+1)*BLOCK_SIZE+idx] = peri_row[i*BLOCK_SIZE+idx];
           array_offset += matrix_dim;
         }
       } else { //peri-col
         idx=tx - BLOCK_SIZE;
         array_offset = (offset+(bx+1)*BLOCK_SIZE)*(size_t)matrix_dim+offset;
         for(i=0; i < BLOCK_SIZE; i++){
           m[array_offset+idx] =  peri_col[i*BLOCK_SIZE+idx];
           array_offset += matrix_dim;
         }
       }
      }
    }

    #pragma omp target teams num_teams(((matrix_dim-i)/BLOCK_SIZE-1) * ((matrix_dim-i)/BLOCK_SIZE-1)) \
                              thread_limit(BLOCK_SIZE*BLOCK_SIZE)
    {
      float peri_row[BLOCK_SIZE * BLOCK_SIZE];
      float peri_col[BLOCK_SIZE * BLOCK_SIZE];
      #pragma omp parallel
      {
        int  bx = omp_get_team_num() % ((matrix_dim-i)/BLOCK_SIZE-1); // item.get_group(1);  
        int  by = omp_get_team_num() / ((matrix_dim-i)/BLOCK_SIZE-1); //omp_get_team_num();  

        int  tx = omp_get_thread_num() % BLOCK_SIZE; //item.get_local_id(1);
        int  ty = omp_get_thread_num() / BLOCK_SIZE; //omp_get_thread_num();

        int i;
        float sum;

        int global_row_id = offset + (by+1)*BLOCK_SIZE;
        int global_col_id = offset + (bx+1)*BLOCK_SIZE;

        peri_row[ty * BLOCK_SIZE + tx] = m[(offset+ty)*(size_t)matrix_dim+global_col_id+tx];
        peri_col[ty * BLOCK_SIZE + tx] = m[(global_row_id+ty)*(size_t)matrix_dim+offset+tx];

        #pragma omp barrier

        sum = 0;
        for (i=0; i < BLOCK_SIZE; i++)
          sum += peri_col[ty * BLOCK_SIZE + i] * peri_row[i * BLOCK_SIZE + tx];
        m[(global_row_id+ty)*(size_t)matrix_dim+global_col_id+tx] -= sum;
      }
    }
  } // for

  offset = i;  // add the offset 
  #pragma omp target teams num_teams(1) thread_limit(BLOCK_SIZE)
  {
    float shadow[BLOCK_SIZE * BLOCK_SIZE];
    #pragma omp parallel
    {
      int i,j;
      int tx = omp_get_thread_num() ;

      size_t array_offset = offset*(size_t)matrix_dim+offset;
      for(i=0; i < BLOCK_SIZE; i++){
        shadow[i * BLOCK_SIZE + tx]=m[array_offset + tx];
        array_offset += matrix_dim;
      }

      #pragma omp barrier

      for(i=0; i < BLOCK_SIZE-1; i++) {
        if (tx>i) {
          for(j=0; j < i; j++)
            shadow[tx * BLOCK_SIZE + i] -= shadow[tx * BLOCK_SIZE + j] * shadow[j * BLOCK_SIZE + i];
          shadow[tx * BLOCK_SIZE + i] /= shadow[i * BLOCK_SIZE + i];
        }

        #pragma omp barrier
        if (tx>i){
          for(j=0; j < i+1; j++)
            shadow[(i+1) * BLOCK_SIZE + tx] -= shadow[(i+1) * BLOCK_SIZE + j]*shadow[j * BLOCK_SIZE + tx];
        }

        #pragma omp barrier
      }

      array_offset = (offset+1)*(size_t)matrix_dim+offset;
      for(i=1; i < BLOCK_SIZE; i++){
        m[array_offset+tx]=shadow[i * BLOCK_SIZE + tx];
        array_offset += matrix_dim;
      }
    }
   }

   auto end = std::chrono::steady_clock::now();
   auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
   printf("Total kernel execution time : %f (s)\n", time * 1e-9f);
  } // #pragma omp target  data map

  /* end of timing point */
  stopwatch_stop(&sw);
  printf("Device offloading time (s): %lf\n", get_interval_by_sec(&sw));

  if (do_verify){
    printf("After LUD\n");
    // print_matrix(m, matrix_dim);
    printf(">>>Verify<<<<\n");
    lud_verify(mm, m, matrix_dim); 
    free(mm);
  }

  free(m);
}

#include <cmath>
#include <cstdlib>
#include <cstdio>
#include <chrono>
#include <omp.h>

void rotate_matrix_parallel (float *matrix, const int n, const int repeat) {
  #pragma omp target data map(tofrom: matrix[0:n*n]) 
  {
    auto start = std::chrono::steady_clock::now();

    for (int i = 0; i < repeat; i++) {
      #pragma omp target teams distribute parallel for thread_limit(256)
      for (int layer = 0; layer < n / 2; ++layer) {
        int first = layer;
        int last = n - 1 - layer;
        for(int i = first; i < last; ++i) {
          int offset = i - first;

          float top = matrix[first*n+i]; // save top
          // left -> top
          matrix[first*n+i] = matrix[(last-offset)*n+first];

          // bottom -> left
          matrix[(last-offset)*n+first] = matrix[last*n+(last-offset)];

          // right -> bottom
          matrix[last*n+(last-offset)] = matrix[i*n+last];

          // top -> right
          matrix[i*n+last] = top; // right <- saved top
        }
      }
    }

    auto end = std::chrono::steady_clock::now();
    auto time = std::chrono::duration_cast<std::chrono::nanoseconds>(end - start).count();
    printf("Average kernel execution time: %f (s)\n", (time * 1e-9f) / repeat);
  }
}

void rotate_matrix_serial(float *matrix, const int n) {
  for (int layer = 0; layer < n / 2; ++layer) {
    int first = layer;
    int last = n - 1 - layer;
    for(int i = first; i < last; ++i) {
      int offset = i - first;
        float top = matrix[first*n+i]; // save top
        // left -> top
        matrix[first*n+i] = matrix[(last-offset)*n+first];

        // bottom -> left
        matrix[(last-offset)*n+first] = matrix[last*n+(last-offset)];

        // right -> bottom
        matrix[last*n+(last-offset)] = matrix[i*n+last];

        // top -> right
        matrix[i*n+last] = top; // right <- saved top
    }
  }
}

int main(int argc, char** argv) {
  if (argc != 3) {
    printf("Usage: %s <matrix size> <repeat>\n", argv[0]);
    return 1;
  }
  const int n = atoi(argv[1]);
  const int repeat = atoi(argv[2]);

  float *serial_res = (float*) aligned_alloc(1024, n*n*sizeof(float));
  float *parallel_res = (float*) aligned_alloc(1024, n*n*sizeof(float));

  for (int i = 0; i < n; i++)
    for (int j = 0; j < n; j++)
      serial_res[i*n+j] = parallel_res[i*n+j] = i*n+j;

  for (int i = 0; i < repeat; i++) {
    rotate_matrix_serial(serial_res, n);
  }

  rotate_matrix_parallel (parallel_res, n, repeat);

  bool ok = true;
  for (int i = 0; i < n; i++) {
    for (int j = 0; j < n; j++) {
      if (serial_res[i*n+j] != parallel_res[i*n+j]) {
        ok = false;
        break;
      }
    }
  }

  printf("%s\n", ok ? "PASS" : "FAIL");

  free(serial_res);
  free(parallel_res);
  return 0;
}

