        for (int t = 0; t < BLOCKS; ++t) {
          int tid_in_tile = t * TILE_WIDTH + lid;
          if (tid_in_tile < N) {
            int row_in_tile = tid_in_tile * D;
            for (int j = 0; j < D; ++j) {
              local_data[local_row + j] = data[row_in_tile + j];
            }
            valid_data[lid] = 1;
          }
          else {
            for (int j = 0; j < D; ++j) {
              local_data[local_row + j] = 0;
            }
            valid_data[lid] = 0;
          }
